}

Method.Source:
    /// <summary>
    /// get the auto extract value for the warehouse
    /// </summary>
    /// <param name = "_metInventLocation">Invent location</param>
    /// <returns>auto extract value</returns>
    public static METAutoExtract metGetAutoExtract(InventLocationId _metInventLocation)
    {
        METAutoExtract metAutoExtract;

        if(_metInventLocation)
        {
            metAutoExtract = (select firstonly inventLocation where inventLocation.InventLocationId == _metInventLocation).METAutoExtract;
        }

        return metAutoExtract;

    }

/// <summary>
/// Get the METInventLocation
/// </summary>
/// <returns>METInventLocation</returns>
public METInventLocation metInventLocation()
{
    return this.SysExtensionSerializerMap::getExtensionTable(tableNum(METinventLocation));
}

    /// <summary>
    /// pack the METInventLocation
    /// </summary>
    /// <param name = "_metInventLocation">METInventLocation to pack</param>
    public void metPackMETInventLocation(METinventLocation  _metInventLocation)
    {
        _metInventLocation.InventLocation = this.RecId;

        this.SysExtensionSerializerMap::packExtensionTable(_metInventLocation);
    }

/// <summary>
/// Inserts a table buffer into the database.
/// </summary>
public void insert()
{
    next insert();
    this.SysExtensionSerializerMap::postInsert();
    
}

/// <summary>
